    const out = API.buildPrelaz(scene, tex, opts, LK), FAR = out && out.dyn && out.dyn.irFar;
    if (FAR && KAVKAZ && API.T && API.T.def.farDem) { const s = kavkaz(FAR, API.T, API.VR.D.base, opts && opts.tier === 0); FAR.upd = update; if (out.stats) out.stats.kavkazVerts = s.verts; }
    return out;
